<template>
 <section class="pg4-demo"><p class="pg4-warning">演示组件 / 非生产组件 · 本地状态 · 不写入业务数据</p>
  <fieldset v-if="name==='Radio'"><legend>参考单选组</legend><label v-for="v in ['阅读','练习','禁用']" :key="v"><input v-model="selected" type="radio" :value="v" :disabled="disabled||v==='禁用'" @change="log('change',selected)"/>{{v}}</label><p>当前：{{selected}}</p></fieldset>
  <div v-else-if="name==='Switch'"><button role="switch" :aria-checked="on" :disabled="disabled" class="pg4-switch" @click="on=!on;log('update:modelValue',on)">{{on?'已开启':'已关闭'}}</button><p>仅控制本地提示；Loading：Not Supported</p></div>
  <div v-else-if="name==='Tooltip'" class="pg4-demo-tools"><span v-for="side in ['top','bottom','left','right']" :key="side" class="pg4-tooltip-anchor"><Button :aria-describedby="tip===side?uid+'tip'+side:undefined" @keydown.esc="tip=''" @focus="tip=side" @blur="tip=''" @mouseenter="tip=side" @mouseleave="tip=''">{{side}}</Button><span v-if="tip===side" :id="uid+'tip'+side" role="tooltip" :class="['pg4-tooltip',side]">本地长文本提示，不代表生产Tooltip已实现</span></span></div>
  <div v-else-if="name==='Tabs'"><div role="tablist" aria-label="参考标签页" @keydown="tabKey"><button v-for="(v,i) in ['概览','长名称：交互和规范','禁用标签']" :id="uid+'tab'+i" :key="v" role="tab" :disabled="i===2" :aria-selected="tab===i" :tabindex="tab===i?0:-1" :aria-controls="uid+'panel'" @click="tab=i;log('change',i)">{{v}}</button></div><div :id="uid+'panel'" role="tabpanel" :aria-labelledby="uid+'tab'+tab">{{tab===0?'组件概览':'属性与交互规范'}}</div></div>
  <div v-else-if="name==='Table'"><div class="pg4-demo-tools"><Button @click="descending=!descending;log('sort',descending)">名称{{descending?'降序':'升序'}}</Button><Checkbox v-model="busy" label="Loading"/><Checkbox v-model="tableEmpty" label="Empty"/><label :for="uid+'table-filter'">筛选名称<input :id="uid+'table-filter'" v-model="tableQuery" @input="page=1;log('filter',tableQuery)"/></label><Checkbox v-model="showTableStatus" label="显示状态列"/></div><div class="pg4-table-scroll"><table :aria-busy="busy"><thead><tr><th>选择</th><th>名称</th><th v-if="showTableStatus">状态</th><th>操作</th></tr></thead><tbody><tr v-if="!tableRows.length"><td :colspan="showTableStatus?4:3">暂无本地数据</td></tr><tr v-for="row in tableRows" :key="row.id"><td><Checkbox v-model="rowsSelected" :value="row.id" :aria-label="'选择'+row.name"/></td><td>{{row.name}}</td><td v-if="showTableStatus">Fixture</td><td><Button size="sm" variant="text" @click="log('row-action',row.id)">查看</Button></td></tr></tbody></table></div><Pagination :page-num="page" :total="filteredTableRows.length" :page-size="3" @change="page=$event"/><p v-if="busy" role="status">模拟加载，不请求API</p></div>
  <div v-else-if="name==='Tree'" role="tree" aria-label="参考知识树"><button role="treeitem" :aria-expanded="expanded" :aria-selected="selected==='根节点'" @click="expanded=!expanded;log('toggle',expanded)" @keydown.right.prevent="expanded=true" @keydown.left.prevent="expanded=false" @keydown.down.prevent="focusNext">{{expanded?'▾':'▸'}} 学习资料</button><div v-if="expanded" role="group"><button v-for="n in ['Java','SQL','禁用节点']" :key="n" role="treeitem" :disabled="n==='禁用节点'" :aria-selected="selected===n" @click="selected=n;log('select',n)" @keydown.down.prevent="focusNext" @keydown.up.prevent="focusPrevious">{{n}}</button></div></div>
  <div v-else-if="name==='Popover'" ref="popover"><Button :aria-expanded="open" @click="open=!open">打开参考浮层</Button><div v-if="open" class="pg4-popover" role="region" aria-label="参考浮层"><p>局部定位，窄屏限制宽度；外部点击/Escape关闭。</p><Button size="sm" @click="open=false">关闭</Button></div></div>
  <div v-else-if="name==='Upload'" @dragover.prevent @drop.prevent="drop"><label>本地文件（TXT/PNG/JPEG，≤2MB）<input type="file" accept=".txt,image/png,image/jpeg" multiple @change="filesChanged"/></label><p>拖入文件或点击选择；从不上传到服务器。</p><p v-if="fileError" role="alert">{{fileError}}</p><ul><li v-for="(f,i) in files" :key="i">{{f.name}}（{{f.size}} bytes）<Button size="sm" variant="text" @click="files.splice(i,1)">移除</Button></li></ul><Checkbox v-model="uploadFailure" label="模拟失败"/><Button :disabled="!files.length" variant="text" @click="clearFiles">清空文件列表</Button><Button :disabled="!files.length||busy" @click="simulateUpload">模拟上传进度</Button><progress :value="progress" max="100">{{progress}}%</progress><p v-if="uploadResult" role="status">{{uploadResult}}</p></div>
  <div v-else-if="name==='Combobox' || name==='SearchInput'"><div class="pg4-demo-tools"><Checkbox v-model="searchLoading" label="模拟 Loading"/><Checkbox v-model="searchError" label="模拟 Error"/></div><p v-if="searchLoading" role="status">本地模拟加载中，不请求网络</p><p v-else-if="searchError" role="alert">本地模拟失败<Button size="sm" variant="text" @click="searchError=false;log('retry','local')">重试</Button></p><label :for="uid+'query'">{{name==='Combobox'?'参考自动建议':'参考搜索'}}</label><div class="pg4-demo-tools"><input :id="uid+'query'" v-model="query" :role="name==='Combobox'?'combobox':undefined" :aria-busy="searchLoading" :aria-expanded="name==='Combobox'?(open&&!searchLoading&&!searchError):undefined" :aria-controls="name==='Combobox'?uid+'list':undefined" :aria-activedescendant="open&&!searchLoading&&!searchError&&matches[active]?uid+'option'+active:undefined" @input="open=true;active=0;log('input',query)" @keydown.down.prevent="open=true;active=Math.min(active+1,matches.length-1)" @keydown.up.prevent="active=Math.max(0,active-1)" @keydown.enter.prevent="choose(matches[active])" @keydown.esc="open=false" placeholder="搜索本地资料"/><Button size="sm" variant="text" @click="query='';open=false;log('clear',null)">清空</Button></div><ul v-if="open&&!searchLoading&&!searchError" :id="uid+'list'" role="listbox"><li v-for="(m,i) in matches" :id="uid+'option'+i" :key="m" role="option" :aria-selected="i===active" @mousedown.prevent="choose(m)">{{m}}</li><li v-if="!matches.length" role="status">没有匹配结果</li></ul><p>当前选择：{{selected}} · 异步网络：Not Supported（本地过滤）</p></div>
  <p v-else>尚未实现可交互参考；此条目不认证任何生产能力。</p>
 </section>
</template>
<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount,useId} from 'vue'
import Button from '@/components/ui/Button.vue'
import Checkbox from '@/components/ui/Checkbox.vue'
import Pagination from '@/components/ui/Pagination.vue'
const props=defineProps<{name:string;disabled?:boolean;fixture?:Record<string,unknown>}>(),emit=defineEmits<{event:[name:string,value:unknown]}>(),uid=useId()
const tableEmpty=ref(!!props.fixture?.tableEmpty),tableQuery=ref(''),showTableStatus=ref(true),searchLoading=ref(!!props.fixture?.searchLoading),searchError=ref(!!props.fixture?.searchError),uploadFailure=ref(false),uploadResult=ref('')
const selected=ref('阅读'),on=ref(false),tip=ref(''),tab=ref(0),descending=ref(false),rowsSelected=ref<number[]>([]),busy=ref(!!props.fixture?.busy),page=ref(1),expanded=ref(true),open=ref(!!props.fixture?.open),popover=ref<HTMLElement>(),query=ref(String(props.fixture?.query||'')),active=ref(0),files=ref<File[]>([]),fileError=ref(''),progress=ref(0)
const filteredTableRows=computed(()=>{if(tableEmpty.value)return [];const rows=Array.from({length:6},(_,i)=>({id:i,name:`本地文档 ${i+1}：这是用于验证长文本的学习资料标题`})).filter(row=>row.name.includes(tableQuery.value));return descending.value?rows.reverse():rows})
const tableRows=computed(()=>filteredTableRows.value.slice((page.value-1)*3,page.value*3))
const matches=computed(()=>['Java 基础','SQL 查询','UI 组件'].filter(n=>n.toLowerCase().includes(query.value.toLowerCase())))
function log(name:string,value:unknown){emit('event',name,value)}
function choose(value?:string){if(!value||searchLoading.value||searchError.value)return;query.value=value;selected.value=value;open.value=false;log('select',value)}
function tabKey(e:KeyboardEvent){if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();tab.value=e.key==='Home'?0:e.key==='End'?1:1-tab.value;const group=(e.currentTarget as HTMLElement);(group.querySelectorAll<HTMLButtonElement>('button')[tab.value])?.focus();log('change',tab.value)}
function focusNext(e:KeyboardEvent){const root=(e.currentTarget as HTMLElement).closest('[role=tree]')!;const list=Array.from(root.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'));list[Math.min(list.indexOf(e.currentTarget as HTMLButtonElement)+1,list.length-1)]?.focus()}
function focusPrevious(e:KeyboardEvent){const root=(e.currentTarget as HTMLElement).closest('[role=tree]')!;const list=Array.from(root.querySelectorAll<HTMLButtonElement>('button:not(:disabled)'));list[Math.max(list.indexOf(e.currentTarget as HTMLButtonElement)-1,0)]?.focus()}
function accept(values:File[]){fileError.value='';for(const file of values){if(file.size>2*1024*1024||!['text/plain','image/png','image/jpeg'].includes(file.type)){fileError.value='文件类型或大小不符合参考限制';continue}files.value.push(file)}log('local-files',files.value.map(f=>({name:f.name,size:f.size})))}
function filesChanged(e:Event){const input=e.target as HTMLInputElement;accept(Array.from(input.files||[]));input.value=''}function drop(e:DragEvent){accept(Array.from(e.dataTransfer?.files||[]))}
let timer:ReturnType<typeof setInterval>|undefined
function clearFiles(){clearInterval(timer);timer=undefined;busy.value=false;progress.value=0;files.value=[];fileError.value='';uploadResult.value='';log('clear-files',null)}
function simulateUpload(){if(busy.value||!files.value.length)return;clearInterval(timer);busy.value=true;progress.value=0;fileError.value='';uploadResult.value='';timer=setInterval(()=>{progress.value+=20;if(uploadFailure.value&&progress.value>=60){clearInterval(timer);timer=undefined;busy.value=false;fileError.value='本地模拟上传失败，可重试；没有请求服务器';log('simulation-error','local')}else if(progress.value>=100){clearInterval(timer);timer=undefined;busy.value=false;uploadResult.value='模拟完成：仅计时器，不是上传成功';log('simulation-complete','仅计时器，不是上传成功')}},100)}
function outside(e:PointerEvent){if(props.name==='Popover'&&!popover.value?.contains(e.target as Node))open.value=false}function key(e:KeyboardEvent){if(e.key==='Escape'){open.value=false;tip.value=''}}
onMounted(()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',key)})
onBeforeUnmount(()=>{clearInterval(timer);document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',key);files.value=[]})
</script>
<style scoped>
.pg4-demo{min-width:0}.pg4-warning{color:var(--kf-muted-foreground);font-size:var(--kf-fs-body-sm);margin-bottom:var(--kf-space-4)}.pg4-demo label,.pg4-demo-tools{display:inline-flex;align-items:center;gap:var(--kf-space-2);flex-wrap:wrap;margin:var(--kf-space-2)}.pg4-demo fieldset{display:grid;gap:var(--kf-space-2)}.pg4-demo input:not([type=radio]):not([type=file]){background:var(--kf-muted);padding:var(--kf-space-3);border-radius:var(--kf-radius-md);min-width:0;max-width:100%;border:0}.pg4-demo input:not([type=radio]):not([type=file]):focus{outline:0;box-shadow:none;border:0}.pg4-demo input[type=radio]{width:20px;height:20px;padding:0;box-shadow:none;accent-color:var(--kf-primary)}.pg4-switch{padding:var(--kf-space-2) var(--kf-space-4);border-radius:var(--kf-radius-full);background:var(--kf-muted)}.pg4-switch[aria-checked=true]{background:var(--kf-primary);color:var(--kf-primary-foreground)}[role=tablist]{display:flex;flex-wrap:wrap;gap:var(--kf-space-2)}[role=tab],[role=treeitem]{padding:var(--kf-space-2);border-radius:var(--kf-radius-sm)}[aria-selected=true]{background:var(--kf-primary-soft)}[role=group]{display:grid;padding-inline-start:var(--kf-space-6)}.pg4-table-scroll{overflow:auto}table{border-collapse:collapse;min-width:32rem;width:100%}td,th{text-align:left;padding:var(--kf-space-3);border-bottom:1px solid var(--kf-border)}.pg4-tooltip-anchor{position:relative}.pg4-tooltip{position:absolute;z-index:5;width:min(12rem,70vw);background:var(--kf-popover);border:1px solid var(--kf-border);padding:var(--kf-space-2);border-radius:var(--kf-radius-sm)}.top{bottom:100%;left:0}.bottom{top:100%;left:0}.left{right:100%;top:0}.right{left:100%;top:0}.pg4-popover{padding:var(--kf-space-4);border:1px solid var(--kf-border);border-radius:var(--kf-radius-md);max-width:20rem}[role=option]{padding:var(--kf-space-2);cursor:pointer}button:focus-visible,input[type=radio]:focus-visible{outline:2px solid var(--kf-ring);outline-offset:2px}
</style>
